begin read only; select jsonb_build_object(
'schemas',(select jsonb_agg(jsonb_build_object('name',nspname,'owner',pg_get_userbyid(nspowner),'grants',(select jsonb_agg(jsonb_build_object('role',case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable)) from aclexplode(coalesce(nspacl,acldefault('n',nspowner))) a))) from pg_namespace where nspname in ('public','private')),
'column_acls',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'column',at.attname,'grants',(select jsonb_agg(jsonb_build_object('role',case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable)) from aclexplode(at.attacl) a))) from pg_attribute at join pg_class c on c.oid=at.attrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and at.attacl is not null),
'sequence_acls',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'grants',(select jsonb_agg(jsonb_build_object('role',case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable)) from aclexplode(coalesce(c.relacl,acldefault('s',c.relowner))) a),'owned_by',(select format('%I.%I.%I',tn.nspname,tc.relname,at.attname) from pg_depend d join pg_class tc on tc.oid=d.refobjid join pg_namespace tn on tn.oid=tc.relnamespace join pg_attribute at on at.attrelid=tc.oid and at.attnum=d.refobjsubid where d.classid='pg_class'::regclass and d.objid=c.oid and d.deptype in ('a','i') limit 1))) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and c.relkind='S'),
'storage_buckets',(select jsonb_agg(jsonb_build_object('id',id,'name',name,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types)) from storage.buckets),
'replica_identity',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'value',c.relreplident)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and c.relkind='r')
) as catalog; commit;
